syntax:
template <class T, class charT = char, class traits = std::char_traits<charT>>
class std::ostream_iterator {
public:
    explicit ostream_iterator(std::basic_ostream<charT, traits>& s, const charT* delim = nullptr);
    ostream_iterator& operator=(const T& value); // writes value to stream
    ostream_iterator& operator*(); // no-op
    ostream_iterator& operator++(); // no-op
    ostream_iterator& operator++(int); // no-op
};

code_example:
#include <iostream>
#include <vector>
#include <iterator>
#include <algorithm>

int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    // Create an ostream_iterator for integers with a comma and space as delimiter
    std::ostream_iterator<int> out_it(std::cout, ", ");
    // Use std::copy to output the vector elements to std::cout
    std::copy(numbers.begin(), numbers.end(), out_it);
    std::cout << std::endl;
    return 0;
}
